package edu.riara.edp.week07;
import javafx.application.Application;import javafx.scene.*;import javafx.scene.canvas.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;
public class MouseKeyDemo extends Application {private double x=100,y=80;public void start(Stage s){Canvas canvas=new Canvas(450,250);Label status=new Label("Click to move; arrow keys to adjust");Runnable paint=()->{GraphicsContext g=canvas.getGraphicsContext2D();g.clearRect(0,0,450,250);g.fillRect(x,y,35,35);};paint.run();canvas.setOnMouseClicked(e->{x=e.getX();y=e.getY();paint.run();});canvas.setOnMouseMoved(e->status.setText("Mouse: "+(int)e.getX()+", "+(int)e.getY()));VBox root=new VBox(status,canvas);Scene scene=new Scene(root,460,290);scene.setOnKeyPressed(e->{switch(e.getCode()){case LEFT->x-=10;case RIGHT->x+=10;case UP->y-=10;case DOWN->y+=10;default->{}}paint.run();});s.setScene(scene);s.show();root.requestFocus();}public static void main(String[]a){launch(a);}}